input.command:
cd /tmp/mlshots; P="$RUN/work"; C="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"; cat > t.html <<EOF
<body><iframe id=f src="file://$P/index.html" style="width:390px;height:800px;border:0"></iframe><pre id=o></pre>
<script>
f.onload=function(){var d=f.contentDocument,w=f.contentWindow,out=[];
out.push('scrollW='+d.documentElement.scrollWidth);
var wide=[].filter.call(d.querySelectorAll('body *'),function(e){var r=e.getBoundingClientRect();return r.right>391&&getComputedStyle(e).position!=='fixed'&&!e.closest('.tide-line')&&!e.closest('.news-waves')&&!e.closest('.site-nav')});
out.push('wide='+wide.slice(0,8).map(function(e){return e.tagName+'.'+e.className}).join(','));
d.querySelector('[data-filter=field-notes]').click();
out.push('visible='+[].filter.call(d.querySelectorAll('.post'),function(p){return !p.hidden}).length+' status='+d.getElementById('filter-status').textContent);
d.querySelector('.nav-toggle').click();
out.push('nav='+w.getComputedStyle(d.getElementById('site-nav')).display);
d.getElementById('theme-toggle').click();
out.push('theme='+d.documentElement.dataset.theme);
o.textContent=out.join('\n');};
</script>
EOF
"$C" --headless=new --disable-gpu --allow-file-access-from-files --disable-web-security --user-data-dir=/tmp/mlshots/prof --virtual-time-budget=4000 --dump-dom file:///tmp/mlshots/t.html 2>/dev/null | sed -n '/<pre/,/<\/pre>/p'

